CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY,email text NOT NULL UNIQUE CHECK(email=lower(email)),display_name text NOT NULL,password_hash text NOT NULL DEFAULT '',platform_admin boolean NOT NULL DEFAULT false,email_verified boolean NOT NULL DEFAULT true,mfa_secret text NOT NULL DEFAULT '',mfa_pending text NOT NULL DEFAULT '',mfa_enabled boolean NOT NULL DEFAULT false,last_totp bigint NOT NULL DEFAULT -1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS platform_state(id boolean PRIMARY KEY DEFAULT true CHECK(id),initialized boolean NOT NULL DEFAULT false);
INSERT INTO platform_state(id) VALUES(true) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,csrf_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS tenants(id uuid PRIMARY KEY,name text NOT NULL,slug text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),quotas jsonb NOT NULL DEFAULT '{"records":100000,"members":1000,"storage_bytes":1073741824,"jobs":1000}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS departments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,parent_id uuid,UNIQUE(tenant_id,id),UNIQUE(tenant_id,name),FOREIGN KEY(tenant_id,parent_id) REFERENCES departments(tenant_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS roles(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),name text NOT NULL,description text NOT NULL DEFAULT '',builtin boolean NOT NULL DEFAULT false,grants jsonb NOT NULL DEFAULT '[]',UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE IF NOT EXISTS memberships(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),user_id uuid NOT NULL REFERENCES users(id),department_id uuid,position text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')),UNIQUE(tenant_id,user_id),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,department_id) REFERENCES departments(tenant_id,id));
CREATE TABLE IF NOT EXISTS member_roles(tenant_id uuid NOT NULL,member_id uuid NOT NULL,role_id uuid NOT NULL,PRIMARY KEY(tenant_id,member_id,role_id),FOREIGN KEY(tenant_id,member_id) REFERENCES memberships(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,role_id) REFERENCES roles(tenant_id,id));
CREATE TABLE IF NOT EXISTS resources(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),module text NOT NULL,owner_id uuid NOT NULL,department_id uuid,version integer NOT NULL DEFAULT 1,data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,owner_id) REFERENCES memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,department_id) REFERENCES departments(tenant_id,id));
CREATE INDEX IF NOT EXISTS resources_module ON resources(tenant_id,module,created_at DESC);
CREATE TABLE IF NOT EXISTS invitations(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),email text NOT NULL,department_id uuid,role_ids jsonb NOT NULL,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,department_id) REFERENCES departments(tenant_id,id));
CREATE TABLE IF NOT EXISTS files(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),owner_id uuid NOT NULL,department_id uuid,name text NOT NULL,size bigint NOT NULL CHECK(size>=0),content_type text NOT NULL,storage_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,owner_id) REFERENCES memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,department_id) REFERENCES departments(tenant_id,id));
CREATE TABLE IF NOT EXISTS jobs(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid NOT NULL,department_id uuid,type text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','succeeded','failed','cancelled')),attempts integer NOT NULL DEFAULT 0,max_attempts integer NOT NULL DEFAULT 3,error text NOT NULL DEFAULT '',payload jsonb NOT NULL DEFAULT '{}',result_key text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,actor_id) REFERENCES memberships(tenant_id,user_id),FOREIGN KEY(tenant_id,department_id) REFERENCES departments(tenant_id,id));
CREATE TABLE IF NOT EXISTS job_leases(job_id uuid PRIMARY KEY REFERENCES jobs(id) ON DELETE CASCADE,tenant_id uuid NOT NULL REFERENCES tenants(id),lease_until timestamptz,claim_token text,next_attempt_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),actor_id uuid,action text NOT NULL,resource text NOT NULL,record_id text NOT NULL DEFAULT '',request_id text NOT NULL,changes jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_tenant ON audit(tenant_id,created_at DESC);
CREATE TABLE IF NOT EXISTS recovery_codes(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash text NOT NULL,PRIMARY KEY(user_id,code_hash));
CREATE TABLE IF NOT EXISTS reset_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS oidc_identities(issuer text NOT NULL,subject text NOT NULL,user_id uuid NOT NULL REFERENCES users(id),PRIMARY KEY(issuer,subject));
CREATE TABLE IF NOT EXISTS oidc_flows(state_hash text PRIMARY KEY,nonce text NOT NULL,verifier_cipher text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS mail_outbox(id uuid PRIMARY KEY,recipient text NOT NULL,payload_cipher text NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,claim_token text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS login_attempts(key text PRIMARY KEY,attempts integer NOT NULL DEFAULT 0,window_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['departments','roles','member_roles','resources','invitations','files','jobs','audit'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab); IF NOT EXISTS(SELECT FROM pg_policies WHERE tablename=tab AND policyname='tenant_isolation') THEN EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id::text = current_setting(''app.tenant_id'',true)) WITH CHECK (tenant_id::text = current_setting(''app.tenant_id'',true))',tab); END IF; END LOOP; END $$;
GRANT USAGE ON SCHEMA public TO tenantforge_app;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO tenantforge_app;
REVOKE ALL ON goose_db_version FROM tenantforge_app;
GRANT SELECT ON goose_db_version TO tenantforge_app;
CREATE TABLE IF NOT EXISTS invitation_tokens(token_hash text PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS storage_gc(id uuid PRIMARY KEY,storage_key text NOT NULL,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON invitation_tokens,storage_gc TO tenantforge_app;
CREATE OR REPLACE FUNCTION resolve_invitation(token text) RETURNS text LANGUAGE sql SET search_path=public AS $$ SELECT tenant_id::text FROM invitation_tokens WHERE token_hash=token AND expires_at>now() $$;
REVOKE ALL ON FUNCTION resolve_invitation(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION resolve_invitation(text) TO tenantforge_app;

